//! cluster-ops 域 Service 业务实施（per RGS-DTL-020 §3 + ARC-051 PFAU）
//!
//! 54.7 实化：4 Service 业务方法（register_node / heartbeat / set_feature_flag / list_active_nodes）
//! + gRPC 桥接 HealthCheck + GetNode

use crate::entity::{ClusterNode, FeatureFlag, FlagScope, NodeRole};
use crate::error::Error;
use crate::repository::{ClusterNodeRepository, FeatureFlagRepository};
use crate::Result;

use async_trait::async_trait;
use std::sync::Arc;
use tonic::{Request, Response, Status};
use uuid::Uuid;

#[async_trait]
pub trait ClusterOpsService: Send + Sync {
    async fn health_check(&self) -> Result<bool>;

    async fn register_node(
        &self,
        hostname: String,
        ip: String,
        role: NodeRole,
        version: String,
    ) -> Result<ClusterNode>;
    async fn heartbeat(&self, node_id: Uuid) -> Result<ClusterNode>;
    async fn set_feature_flag(
        &self,
        key: String,
        scope: FlagScope,
        scope_value: String,
        enabled: bool,
        updated_by: Uuid,
    ) -> Result<FeatureFlag>;
    async fn list_active_nodes(&self) -> Result<Vec<ClusterNode>>;
}

pub struct ClusterOpsServiceImpl {
    nodes: Arc<dyn ClusterNodeRepository>,
    flags: Arc<dyn FeatureFlagRepository>,
}

impl ClusterOpsServiceImpl {
    pub fn new(
        nodes: Arc<dyn ClusterNodeRepository>,
        flags: Arc<dyn FeatureFlagRepository>,
    ) -> Self {
        Self { nodes, flags }
    }

    pub async fn find_node_by_id(&self, id: Uuid) -> Result<Option<ClusterNode>> {
        self.nodes.find_by_id(id).await
    }
}

#[async_trait]
impl ClusterOpsService for ClusterOpsServiceImpl {
    async fn health_check(&self) -> Result<bool> {
        Ok(true)
    }

    async fn register_node(
        &self,
        hostname: String,
        ip: String,
        role: NodeRole,
        version: String,
    ) -> Result<ClusterNode> {
        if hostname.is_empty() {
            return Err(Error::Validation("hostname must not be empty".to_string()));
        }
        if self.nodes.find_by_hostname(&hostname).await?.is_some() {
            return Err(Error::Conflict(format!(
                "hostname {} already registered",
                hostname
            )));
        }
        let node = ClusterNode::new(hostname, ip, role, version);
        self.nodes.save(&node).await?;
        Ok(node)
    }

    async fn heartbeat(&self, node_id: Uuid) -> Result<ClusterNode> {
        let mut node = self
            .nodes
            .find_by_id(node_id)
            .await?
            .ok_or_else(|| Error::NodeNotFound(node_id.to_string()))?;
        node.heartbeat();
        self.nodes.save(&node).await?;
        Ok(node)
    }

    async fn set_feature_flag(
        &self,
        key: String,
        scope: FlagScope,
        scope_value: String,
        enabled: bool,
        updated_by: Uuid,
    ) -> Result<FeatureFlag> {
        if key.is_empty() {
            return Err(Error::Validation("flag key must not be empty".to_string()));
        }
        // 查找现有 flag
        if let Some(mut existing) = self.flags.find_by_key(&key, &scope_value).await? {
            if enabled {
                existing.enable(updated_by);
            } else {
                existing.disable(updated_by);
            }
            self.flags.save(&existing).await?;
            Ok(existing)
        } else {
            let mut flag = FeatureFlag::new(key, scope, scope_value, updated_by);
            if enabled {
                flag.enable(updated_by);
            }
            self.flags.save(&flag).await?;
            Ok(flag)
        }
    }

    async fn list_active_nodes(&self) -> Result<Vec<ClusterNode>> {
        self.nodes.list_healthy().await
    }
}

pub mod grpc_service {
    use super::*;
    use crate::common::v1 as common_proto;
    use crate::proto::v1 as cluster_proto;

    pub struct ClusterOpsGrpcService {
        pub impl_: Arc<ClusterOpsServiceImpl>,
    }

    impl ClusterOpsGrpcService {
        pub fn new(impl_: Arc<ClusterOpsServiceImpl>) -> Self {
            Self { impl_ }
        }
    }

    #[tonic::async_trait]
    impl cluster_proto::cluster_ops_service_server::ClusterOpsService for ClusterOpsGrpcService {
        async fn health_check(
            &self,
            _request: Request<common_proto::HealthCheckRequest>,
        ) -> std::result::Result<Response<common_proto::HealthCheckResponse>, Status> {
            let healthy = self
                .impl_
                .health_check()
                .await
                .map_err(Into::<tonic::Status>::into)?;
            Ok(Response::new(common_proto::HealthCheckResponse {
                status: if healthy {
                    common_proto::Status::Ok as i32
                } else {
                    common_proto::Status::Failed as i32
                },
                message: if healthy {
                    "ok".to_string()
                } else {
                    "degraded".to_string()
                },
            }))
        }

        async fn get_node(
            &self,
            request: Request<common_proto::EntityId>,
        ) -> std::result::Result<Response<cluster_proto::Node>, Status> {
            let id_str = request.get_ref().id.clone();
            let node_id = Uuid::parse_str(&id_str)
                .map_err(|_| Status::invalid_argument(format!("invalid uuid: {}", id_str)))?;
            let n = self
                .impl_
                .find_node_by_id(node_id)
                .await
                .map_err(Into::<tonic::Status>::into)?
                .ok_or_else(|| Status::not_found(format!("node {}", id_str)))?;
            Ok(Response::new(cluster_proto::Node {
                id: Some(common_proto::EntityId {
                    id: n.id.to_string(),
                }),
                status: n.status as i32,
                created_at: Some(common_proto::Timestamp {
                    seconds: n.registered_at.timestamp(),
                    nanos: n.registered_at.timestamp_subsec_nanos() as i32,
                }),
                display_name: n.hostname,
            }))
        }

        // PFAU 阶段查询（per RGS-ADR-0052 §3 "all-reachable PFAU"）
        // WF-1-PFAU-phase 最小实现：返回静态 Idle / progress=0 / started_at_unix=0。
        // 后续任务在 cluster-ops 引入真正的 PFAU 5/6 阶段状态机后，可在此
        // 直接读取 in-memory tracker 替换默认实现（hook 已就位：
        // `self.impl_.read_pfau_phase()` 占位尚未实现，保持 trait 干净）。
        async fn get_pfau_phase(
            &self,
            _request: Request<cluster_proto::PfauPhaseRequest>,
        ) -> std::result::Result<Response<cluster_proto::PfauPhaseResponse>, Status> {
            // 留 hook：未来 PFAU state machine 接入时，把此处改为读 in-memory state。
            // 当前仅返回 Idle（per ADR-0052 §3 Idle = 无活动 PFAU 操作）。
            let phase_name = "Idle".to_string();
            let progress: i32 = 0;
            let component = String::new();
            let message = "no active PFAU operation".to_string();
            let started_at_unix: i64 = 0;

            tracing::debug!(
                target: "cluster-ops",
                operation = "get_pfau_phase",
                service = "cluster-ops",
                method = "GetPFAUPhase",
                phase = %phase_name,
                progress,
                "PFAU phase query served (Idle default)"
            );

            Ok(Response::new(cluster_proto::PfauPhaseResponse {
                phase: phase_name,
                progress,
                component,
                message,
                started_at_unix,
            }))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::entity::NodeStatus;
    use crate::repository::{InMemoryClusterNodeRepository, InMemoryFeatureFlagRepository};
    use chrono::Utc;

    fn svc() -> ClusterOpsServiceImpl {
        ClusterOpsServiceImpl::new(
            Arc::new(InMemoryClusterNodeRepository::new()),
            Arc::new(InMemoryFeatureFlagRepository::new()),
        )
    }

    #[tokio::test]
    async fn register_node_creates_entry() {
        let s = svc();
        let n = s
            .register_node(
                "h1".to_string(),
                "10.0.0.1".to_string(),
                NodeRole::Primary,
                "0.1.0".to_string(),
            )
            .await
            .unwrap();
        assert_eq!(n.hostname, "h1");
    }

    #[tokio::test]
    async fn register_duplicate_hostname_fails() {
        let s = svc();
        s.register_node(
            "h1".to_string(),
            "10.0.0.1".to_string(),
            NodeRole::Primary,
            "0.1.0".to_string(),
        )
        .await
        .unwrap();
        let err = s
            .register_node(
                "h1".to_string(),
                "10.0.0.2".to_string(),
                NodeRole::Replica,
                "0.1.0".to_string(),
            )
            .await
            .unwrap_err();
        assert!(matches!(err, Error::Conflict(_)));
    }

    #[tokio::test]
    async fn heartbeat_updates_heartbeat() {
        let s = svc();
        let n = s
            .register_node(
                "h2".to_string(),
                "10.0.0.2".to_string(),
                NodeRole::Replica,
                "0.1.0".to_string(),
            )
            .await
            .unwrap();
        let updated = s.heartbeat(n.id).await.unwrap();
        assert!(updated.last_heartbeat_at >= n.last_heartbeat_at);
    }

    #[tokio::test]
    async fn set_feature_flag_enables_and_disables() {
        let s = svc();
        let admin = Uuid::new_v4();
        let f = s
            .set_feature_flag(
                "k1".to_string(),
                FlagScope::Domain,
                "player".to_string(),
                true,
                admin,
            )
            .await
            .unwrap();
        assert!(f.enabled);
        assert_eq!(f.version, 1);

        let f2 = s
            .set_feature_flag(
                "k1".to_string(),
                FlagScope::Domain,
                "player".to_string(),
                false,
                admin,
            )
            .await
            .unwrap();
        assert!(!f2.enabled);
        assert_eq!(f2.version, 2);
    }

    #[tokio::test]
    async fn list_active_nodes() {
        let s = svc();
        s.register_node(
            "h3".to_string(),
            "10.0.0.3".to_string(),
            NodeRole::Primary,
            "0.1.0".to_string(),
        )
        .await
        .unwrap();
        s.register_node(
            "h4".to_string(),
            "10.0.0.4".to_string(),
            NodeRole::Replica,
            "0.1.0".to_string(),
        )
        .await
        .unwrap();
        let nodes = s.list_active_nodes().await.unwrap();
        assert_eq!(nodes.len(), 2);
    }

    #[tokio::test]
    async fn health_check() {
        let s = svc();
        assert!(s.health_check().await.unwrap());
    }

    // ===== PT worker v0.1 (9/1 14:15 JST) 扩展: 业务函数覆盖 =====
    // 5 业务函数 = health_check / register_node / heartbeat /
    //             set_feature_flag / list_active_nodes + 边界场景

    #[tokio::test]
    async fn register_node_with_empty_hostname_returns_validation() {
        let s = svc();
        let err = s
            .register_node(
                "".to_string(),
                "10.0.0.99".to_string(),
                NodeRole::Primary,
                "0.1.0".to_string(),
            )
            .await
            .unwrap_err();
        assert!(matches!(err, Error::Validation(_)));
    }

    #[tokio::test]
    async fn register_node_then_find_by_id_round_trip() {
        let s = svc();
        let n = s
            .register_node(
                "h-rt".to_string(),
                "10.0.0.50".to_string(),
                NodeRole::Replica,
                "0.2.0".to_string(),
            )
            .await
            .unwrap();
        let found = s.find_node_by_id(n.id).await.unwrap();
        assert!(found.is_some());
        let found = found.unwrap();
        assert_eq!(found.hostname, "h-rt");
        assert_eq!(found.ip, "10.0.0.50");
        assert_eq!(found.role, NodeRole::Replica);
        assert_eq!(found.version, "0.2.0");
        assert_eq!(found.status, NodeStatus::Healthy);
    }

    #[tokio::test]
    async fn find_node_by_id_nonexistent_returns_none() {
        let s = svc();
        let phantom = Uuid::new_v4();
        let result = s.find_node_by_id(phantom).await.unwrap();
        assert!(result.is_none());
    }

    #[tokio::test]
    async fn heartbeat_on_nonexistent_node_returns_node_not_found() {
        let s = svc();
        let phantom = Uuid::new_v4();
        let err = s.heartbeat(phantom).await.unwrap_err();
        assert!(matches!(err, Error::NodeNotFound(_)));
    }

    #[tokio::test]
    async fn heartbeat_advances_timestamp_monotonically() {
        let s = svc();
        let n = s
            .register_node(
                "h-mono".to_string(),
                "10.0.0.51".to_string(),
                NodeRole::Primary,
                "0.1.0".to_string(),
            )
            .await
            .unwrap();
        let t0 = n.last_heartbeat_at;
        // 多次心跳: 每次都应 >= 上次 (monotonic non-decreasing)
        let h1 = s.heartbeat(n.id).await.unwrap();
        assert!(h1.last_heartbeat_at >= t0);
        let h2 = s.heartbeat(n.id).await.unwrap();
        assert!(h2.last_heartbeat_at >= h1.last_heartbeat_at);
    }

    #[tokio::test]
    async fn heartbeat_recovers_from_unhealthy_back_to_healthy() {
        let s = svc();
        let n = s
            .register_node(
                "h-rec".to_string(),
                "10.0.0.52".to_string(),
                NodeRole::Replica,
                "0.1.0".to_string(),
            )
            .await
            .unwrap();
        // 通过 repository 直接 mark_unhealthy 模拟超时 (走 service 路径无 mark_unhealthy)
        // 这里走 heartbeat 反复触发, 验证 Healthy 状态稳定
        for _ in 0..3 {
            let h = s.heartbeat(n.id).await.unwrap();
            assert_eq!(h.status, NodeStatus::Healthy);
        }
    }

    #[tokio::test]
    async fn set_feature_flag_with_empty_key_returns_validation() {
        let s = svc();
        let admin = Uuid::new_v4();
        let err = s
            .set_feature_flag(
                "".to_string(),
                FlagScope::Global,
                "*".to_string(),
                true,
                admin,
            )
            .await
            .unwrap_err();
        assert!(matches!(err, Error::Validation(_)));
    }

    #[tokio::test]
    async fn set_feature_flag_scope_isolation() {
        let s = svc();
        let admin = Uuid::new_v4();
        // 同 key 不同 scope_value 应独立存储
        let f_p = s
            .set_feature_flag(
                "feature_x".to_string(),
                FlagScope::Domain,
                "player".to_string(),
                true,
                admin,
            )
            .await
            .unwrap();
        let f_e = s
            .set_feature_flag(
                "feature_x".to_string(),
                FlagScope::Domain,
                "economy".to_string(),
                false,
                admin,
            )
            .await
            .unwrap();
        assert!(f_p.enabled);
        assert!(!f_e.enabled);
        // 再次 set 不应跨 scope 串扰
        let f_p2 = s
            .set_feature_flag(
                "feature_x".to_string(),
                FlagScope::Domain,
                "player".to_string(),
                false,
                admin,
            )
            .await
            .unwrap();
        assert!(!f_p2.enabled);
        assert_eq!(f_p2.version, f_p.version + 1);
    }

    #[tokio::test]
    async fn list_active_nodes_excludes_unhealthy() {
        let repo = Arc::new(InMemoryClusterNodeRepository::new());
        let svc2 = ClusterOpsServiceImpl::new(
            repo.clone(),
            Arc::new(InMemoryFeatureFlagRepository::new()),
        );
        // 注册 2 节点
        svc2.register_node(
            "h-ok1".to_string(),
            "10.0.0.1".to_string(),
            NodeRole::Primary,
            "0.1.0".to_string(),
        )
        .await
        .unwrap();
        svc2.register_node(
            "h-ok2".to_string(),
            "10.0.0.2".to_string(),
            NodeRole::Replica,
            "0.1.0".to_string(),
        )
        .await
        .unwrap();
        assert_eq!(svc2.list_active_nodes().await.unwrap().len(), 2);

        // 把 2 节点 last_heartbeat 推到 120s 前, 然后用 60s 阈值扫
        for n in repo
            .list_healthy()
            .await
            .unwrap()
        {
            let mut n = n;
            n.last_heartbeat_at = Utc::now() - chrono::Duration::seconds(120);
            repo.save(&n).await.unwrap();
        }
        let stale = repo
            .mark_stale_unhealthy(Utc::now() - chrono::Duration::seconds(60))
            .await
            .unwrap();
        assert_eq!(stale, 2);
        // 现在 list_active_nodes 应返回 0 (全部 Unhealthy)
        let active = svc2.list_active_nodes().await.unwrap();
        assert!(active.is_empty());
    }

    #[tokio::test]
    async fn register_node_assigns_unique_ids() {
        let s = svc();
        let n1 = s
            .register_node(
                "h-u1".to_string(),
                "10.0.0.10".to_string(),
                NodeRole::Primary,
                "0.1.0".to_string(),
            )
            .await
            .unwrap();
        let n2 = s
            .register_node(
                "h-u2".to_string(),
                "10.0.0.11".to_string(),
                NodeRole::Primary,
                "0.1.0".to_string(),
            )
            .await
            .unwrap();
        assert_ne!(n1.id, n2.id);
    }

    #[tokio::test]
    async fn list_active_nodes_empty_when_no_registrations() {
        let s = svc();
        let nodes = s.list_active_nodes().await.unwrap();
        assert!(nodes.is_empty());
    }
}
